def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def jdump(x: Any) -> str:
    return json.dumps(x, ensure_ascii=False, default=str, sort_keys=True)


def cfg_hash(x: Mapping[str, Any]) -> str:
    return hashlib.sha256(jdump(x).encode("utf-8")).hexdigest()


def append_jsonl(path: Path, obj: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as f:
        f.write(json.dumps(dict(obj), ensure_ascii=False, default=str) + "\n")


def load_latest(path: Path, h: str, key: str = "source_row_index") -> Dict[int, Dict[str, Any]]:
    out: Dict[int, Dict[str, Any]] = {}
    if not path.exists():
        return out
    with path.open(encoding="utf-8") as f:
        for line in f:
            try:
                o = json.loads(line)
                if o.get("config_hash") == h and key in o:
                    out[int(o[key])] = o
            except Exception:
                pass
    return out


def load_module(path: str, name: str):
    p = Path(path)
    if not p.exists():
        raise FileNotFoundError(p)
    spec = importlib.util.spec_from_file_location(name, p)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Cannot load {p}")
    mod = importlib.util.module_from_spec(spec)
    sys.modules[name] = mod
    spec.loader.exec_module(mod)
    return mod


def load_embedded_module(blob: str, name: str, virtual_filename: str):
    source = gzip.decompress(base64.b64decode(blob.encode("ascii"))).decode("utf-8")
    mod = types.ModuleType(name)
    mod.__file__ = virtual_filename
    mod.__package__ = ""
    sys.modules[name] = mod
    exec(compile(source, virtual_filename, "exec"), mod.__dict__)
    return mod


def import_project_modules(args):
    v4 = load_module(args.v4_script, "trbm_v4_source") if args.v4_script else load_embedded_module(
        EMBEDDED_V4_GZ_B64, "trbm_v4_source", "<embedded_v4_flare_vax.py>"
    )
    v5 = load_module(args.v5_script, "trbm_v5_source") if args.v5_script else load_embedded_module(
        EMBEDDED_V5_GZ_B64, "trbm_v5_source", "<embedded_v5_flare_vax.py>"
    )
    return v4, v5


def target_binary(v: Any) -> Optional[int]:
    try:
        iv = int(float(v))
        return 1 if iv == 1 else (0 if iv == 2 else None)
    except Exception:
        return None


def safe_logit(p: Any) -> np.ndarray:
    p = np.clip(np.asarray(p, dtype=float), 1e-6, 1 - 1e-6)
    return np.log(p / (1 - p))


def sigmoid(x: Any) -> np.ndarray:
    x = np.clip(np.asarray(x, dtype=float), -40, 40)
    return 1.0 / (1.0 + np.exp(-x))


def prepare_raw(input_csv: str, v4, v5, variants: Sequence[str]) -> pd.DataFrame:
    needed: Set[str] = set()
    if "v4" in variants:
        needed.update(v4.REQUIRED_COLUMNS)
    if "v5" in variants:
        needed.update(v5.REQUIRED_COLUMNS)
    header = set(pd.read_csv(input_csv, nrows=0).columns)
    missing = sorted(needed - header)
    if missing:
        raise KeyError(f"adult24.csv missing columns: {missing}")
    raw = pd.read_csv(input_csv, usecols=sorted(needed), low_memory=False)
    raw.index = np.arange(len(raw), dtype=int)
    return raw


def build_variant_scores(raw_all: pd.DataFrame, variant: str, v4, v5):
    if variant == "v4":
        raw = raw_all[list(v4.REQUIRED_COLUMNS)].copy()
        scores = v4.build_scores(raw)
        second = "vaccine_acceptance_benefit_proxy"
    else:
        raw = raw_all[list(v5.REQUIRED_COLUMNS)].copy()
        scores = v5.apply_construct_config(v5.build_scores(raw), v5.load_construct_config(""))
        second = "preventive_engagement_proxy"
    valid = scores["vaccinated"].isin([0, 1])
    raw = raw.loc[valid].copy()
    scores = scores.loc[valid].copy()
    scores["source_row_index"] = scores.index.astype(int)
    return raw, scores, second


def load_reference_split(path: str, raw_all: pd.DataFrame) -> pd.DataFrame:
    ref = pd.read_csv(path)
    pairs = [
        ("source_index", "phase"),
        ("source_row_index", "split"),
        ("source_index", "split"),
        ("source_row_index", "phase"),
    ]
    pair = next((x for x in pairs if set(x).issubset(ref.columns)), None)
    if pair is None:
        raise ValueError(f"Unsupported reference split format: {path}")
    a, b = pair
    out = ref[[a, b]].copy()
    out.columns = ["source_row_index", "split"]
    out["source_row_index"] = pd.to_numeric(out["source_row_index"], errors="raise").astype(int)
    out["split"] = out["split"].astype(str).str.lower()
    out = out[out["split"].isin(["memory", "calibration", "test"])].drop_duplicates("source_row_index")
    out = out[out["source_row_index"].isin(raw_all.index)].copy()
    out["actual"] = [target_binary(raw_all.loc[i, TARGET]) for i in out["source_row_index"]]
    return out[out["actual"].isin([0, 1])].reset_index(drop=True)


def fallback_split(scores: pd.DataFrame, seed: int) -> pd.DataFrame:
    idx = np.asarray(scores.index, dtype=int)
    y = scores["vaccinated"].astype(int)
    n = len(idx)
    n_memory = int(round(0.40 * n))
    n_cal = int(round(0.20 * n))
    mem, rest = train_test_split(idx, train_size=n_memory, random_state=seed, stratify=y.loc[idx])
    cal, test = train_test_split(rest, train_size=n_cal, random_state=seed + 1, stratify=y.loc[rest])
    rows: List[Dict[str, Any]] = []
    for split, arr in [("memory", mem), ("calibration", cal), ("test", test)]:
        rows.extend({"source_row_index": int(i), "split": split, "actual": int(y.loc[i])} for i in arr)
    return pd.DataFrame(rows)


def downsample_eval(assignments: pd.DataFrame, sample_size: int, seed: int) -> pd.DataFrame:
    if sample_size <= 0:
        return assignments.copy()
    target = assignments[assignments["split"].isin(["calibration", "test"])].copy()
    if sample_size >= len(target):
        return assignments.copy()
    pieces = []
    groups = list(target.groupby(["split", "actual"], sort=True))
    alloc = [max(1, int(round(sample_size * len(g) / len(target)))) for _, g in groups]
    while sum(alloc) > sample_size:
        changed = False
        for i in range(len(alloc) - 1, -1, -1):
            if alloc[i] > 1:
                alloc[i] -= 1
                changed = True
                if sum(alloc) == sample_size:
                    break
        if not changed:
            break
    while sum(alloc) < sample_size:
        changed = False
        for i, (_, g) in enumerate(groups):
            if alloc[i] < len(g):
                alloc[i] += 1
                changed = True
                if sum(alloc) == sample_size:
                    break
        if not changed:
            break
    for j, (_, g) in enumerate(groups):
        pieces.append(g.sample(n=min(alloc[j], len(g)), random_state=seed + j))
    return pd.concat([assignments[assignments["split"] == "memory"], pd.concat(pieces)], ignore_index=True)


